window.__texto({"id": "740304990", "paragrafos": [{"c": "identifica", "t": "PORTARIA MPA Nº 779, DE 23 DE OUTUBRO DE 2026"}, {"c": "ementa", "t": "Submete à consulta pública a proposta de ato normativo que estabelece os critérios e os procedimentos administrativos para a inscrição no Registro Geral da Atividade Pesqueira, na categoria Embarcação de Pesca, que opera na captura de recursos pesqueiros em águas continentais."}, {"c": "dou-paragraph", "t": "O MINISTRO DE ESTADO DA PESCA E AQUICULTURA, no uso da atribuição que lhe confere o art. 87, parágrafo único, inciso II, da Constituição, e em vista do disposto na Lei nº 14.600, de 19 de junho de 2023, no Decreto nº 10.411, de 30 de junho de 2020, e no Decreto nº 11.624, de 1º de agosto de 2023, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica submetida à consulta pública a proposta de ato normativo que estabelece os critérios e os procedimentos administrativos para a inscrição no Registro Geral da Atividade Pesqueira, na categoria Embarcação de Pesca, que opera na captura de recursos pesqueiros em águas continentais, constante do Anexo."}, {"c": "dou-paragraph", "t": "Parágrafo único. As informações e os documentos relativos à proposta de que trata o caput estarão disponíveis, a partir da data de publicação desta Portaria, no sítio eletrônico oficial do Ministério da Pesca e Aquicultura, https://www.gov.br/mpa/pt-br, e na Plataforma Brasil Participativo, https://brasilparticipativo.presidencia.gov.br."}, {"c": "dou-paragraph", "t": "Art. 2º Os interessados poderão apresentar manifestações destinadas ao aprimoramento da proposta de que trata o art. 1º, exclusivamente por meio da Plataforma Brasil Participativo, no prazo de quarenta e cinco dias corridos, contado da data de publicação desta Portaria."}, {"c": "dou-paragraph", "t": "Art. 3º Esta Portaria entra em vigor na data de sua publicação."}, {"c": "assina", "t": "RIVETLA EDIPO ARAUJO CRUZ"}, {"c": "dou-paragraph", "t": "ANEXOPROPOSTA DE ATO NORMATIVO"}, {"c": "dou-paragraph", "t": "PORTARIA MPA Nº , DE DE DE 2026"}, {"c": "dou-paragraph", "t": "Estabelece os critérios e os procedimentos administrativos para a inscrição no Registro Geral da Atividade Pesqueira, na categoria Embarcação de Pesca, que opera na captura de recursos pesqueiros em águas continentais."}, {"c": "dou-paragraph", "t": "O MINISTRO DE ESTADO DA PESCA E AQUICULTURA, no uso da atribuição que lhe confere o art. 87, parágrafo único, inciso II, da Constituição, e em vista do disposto na Lei nº 11.959, de 29 de junho de 2009, na Lei nº 14.600, de 19 de junho de 2023, no Decreto nº 8.425, de 31 de março de 2015, e no Decreto nº 11.624, de 1º de agosto de 2023, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam estabelecidos os critérios e os procedimentos administrativos para a inscrição no Registro Geral da Atividade Pesqueira, na categoria Embarcação de Pesca, que opera na captura de recursos pesqueiros em águas continentais, de acordo com a matriz de permissionamento estabelecida na Portaria [inserir portaria da matriz de permissionamento] e suas alterações."}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES PRELIMINARES"}, {"c": "dou-paragraph", "t": "Art. 2º Para os fins desta Portaria, entende-se por:"}, {"c": "dou-paragraph", "t": "I - Permissão Prévia de Pesca: ato administrativo discricionário e precário, condicionado ao interesse público, pelo qual é permitido ao responsável legal pela embarcação a construção, a substituição, a conversão de modalidade, a transformação e a importação de embarcação de pesca;"}, {"c": "dou-paragraph", "t": "II - Autorização de Pesca: ato administrativo discricionário e precário, condicionado ao interesse público, pelo qual é permitido à embarcação de pesca operar na captura de recursos pesqueiros para fins comerciais em águas continentais, emitido no Sistema Eletrônico do Registro Geral da Atividade Pesqueira;"}, {"c": "dou-paragraph", "t": "III - transformação: alteração das características físicas da embarcação de pesca, podendo ser volume do porão, potência do motor, arqueação bruta, comprimento total, tipo de propulsão e tancagem;"}, {"c": "dou-paragraph", "t": "IV - conversão: alteração da modalidade de pesca constante da Autorização de Pesca;"}, {"c": "dou-paragraph", "t": "V - substituição: transferência de Autorização de Pesca entre embarcações de pesca, que pode ocorrer em casos de naufrágio, destruição ou desativação da embarcação;"}, {"c": "dou-paragraph", "t": "VI - desativação: ato pelo qual o responsável legal promove o afastamento definitivo da embarcação de pesca da atividade pesqueira, mediante renúncia expressa da Autorização de Pesca concedida;"}, {"c": "dou-paragraph", "t": "VII - atualização de dados: alteração da nomenclatura, troca de titularidade, inclusão de arrendatário, correção dos dados cadastrais do responsável legal, inclusão de inventariante, alteração da quantidade de tripulantes, comunicação de falecimento do responsável legal e alteração de jurisdição; e"}, {"c": "dou-paragraph", "t": "VIII - responsável legal: pessoa física ou jurídica que figure como proprietária, coproprietária, arrendatária ou inventariante da embarcação de pesca."}, {"c": "dou-paragraph", "t": "Art. 3º Toda embarcação de pesca destinada à captura de recursos pesqueiros para fins comerciais em águas continentais deverá estar previamente inscrita no Registro Geral da Atividade Pesqueira, na categoria de Embarcação de Pesca, e possuir Autorização de Pesca válida."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os procedimentos administrativos para as embarcações de pesca que desenvolvem demais atividades previstas na Lei nº 11.959, de 29 de junho de 2009, deverão seguir regramento específico estabelecido pelo Ministério da Pesca e Aquicultura."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DOS PROCEDIMENTOS PARA PERMISSÃO PRÉVIA DE PESCA E DE AUTORIZAÇÃO DE PESCA"}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Dos objetivos e critérios para requerimento da Permissão Prévia de Pesca e da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 4º A inscrição de embarcação de pesca no Registro Geral da Atividade Pesqueira observará, quando cabível, duas etapas administrativas sucessivas:"}, {"c": "dou-paragraph", "t": "I - obtenção da Permissão Prévia de Pesca; e"}, {"c": "dou-paragraph", "t": "II - obtenção da Autorização de Pesca."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Autorização de Pesca somente será concedida após o cumprimento dos requisitos previstos nesta Portaria e da obtenção da Permissão Prévia de Pesca, quando exigida."}, {"c": "dou-paragraph", "t": "Art. 5º A Permissão Prévia de Pesca terá numeração única e vigência de dois anos, contados da data de sua expedição."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Permissão Prévia de Pesca não autoriza a operação da embarcação de pesca no exercício da atividade pesqueira."}, {"c": "dou-paragraph", "t": "Art. 6º A Autorização de Pesca terá numeração única e vigência de dez anos, contados da data de sua expedição."}, {"c": "dou-paragraph", "t": "Art. 7º Os requerimentos de Permissão Prévia de Pesca e de Autorização de Pesca de que trata esta Portaria deverão ser apresentados por meio do Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento da Permissão Prévia de Pesca para construção de embarcação de pesca"}, {"c": "dou-paragraph", "t": "Art. 8º Para requerer a Permissão Prévia de Pesca para construção de embarcação de pesca, o responsável legal deverá apresentar a seguinte documentação legível e sem rasuras:"}, {"c": "dou-paragraph", "t": "I - formulário de requerimento devidamente preenchido e assinado, conforme Anexo I;"}, {"c": "dou-paragraph", "t": "II - cópia colorida do documento oficial de identidade ou de identificação pessoal do responsável legal da embarcação de pesca, quando pessoa física, ou do responsável legal ou do administrador da pessoa jurídica, conforme o caso; e"}, {"c": "dou-paragraph", "t": "III - cópia de comprovante de residência do responsável legal pessoa física, atualizado e emitido no máximo há três meses, ou autodeclaração de residência, conforme Anexo II, sendo que, no caso de responsável legal pessoa jurídica, o endereço será obtido pelo Ministério da Pesca e Aquicultura mediante consulta à base cadastral do Cadastro Nacional da Pessoa Jurídica  CNPJ."}, {"c": "dou-paragraph", "t": "§ 1º O responsável legal com idade entre dezoito e vinte e um anos poderá apresentar comprovante de residência em nome de membro do grupo familiar."}, {"c": "dou-paragraph", "t": "§ 2º Quando a embarcação de pesca já estiver construída, deverá ser apresentada, também, cópia válida do respectivo Título de Inscrição de Embarcação  TIE ou Título de Inscrição de Embarcação Miúda  TIEM, no qual conste expressamente a atividade de pesca, com expedição até a data de publicação desta Portaria."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento da Permissão Prévia de Pesca para substituição, conversão e transformação de embarcação de pesca"}, {"c": "dou-paragraph", "t": "Art. 9º Para requerer a Permissão Prévia de Pesca para transformação, conversão ou substituição de embarcação de pesca, o responsável legal deverá apresentar a seguinte documentação legível e sem rasuras:"}, {"c": "dou-paragraph", "t": "I - formulário de requerimento devidamente preenchido e assinado, conforme Anexo I;"}, {"c": "dou-paragraph", "t": "II - cópia colorida do documento oficial de identidade ou de identificação pessoal do responsável legal da embarcação de pesca, quando pessoa física, ou do responsável legal ou do administrador da pessoa jurídica, conforme o caso;"}, {"c": "dou-paragraph", "t": "III - cópia de comprovante de residência do responsável legal pessoa física, atualizado e emitido no máximo há três meses, ou autodeclaração de residência, conforme Anexo II, sendo que, no caso de responsável legal pessoa jurídica, o endereço será obtido pelo Ministério da Pesca e Aquicultura mediante consulta à base cadastral do Cadastro Nacional da Pessoa Jurídica  CNPJ;"}, {"c": "dou-paragraph", "t": "IV - duas fotos coloridas da embarcação, uma mostrando-a pela popa (traseira) e outra pelo través (lado), de forma que apareça total e claramente de proa a popa;"}, {"c": "dou-paragraph", "t": "V - cópia válida e atualizada do TIE ou do TIEM, no qual conste expressamente a atividade de pesca;"}, {"c": "dou-paragraph", "t": "VI - cópia do Memorial Descritivo que contenha as características básicas da embarcação de pesca, incluídos o comprimento total, a arqueação bruta, a arqueação líquida, a potência do motor, a capacidade do porão de armazenamento do pescado e a tancagem, com identificação e assinatura do responsável técnico pelo projeto; e"}, {"c": "dou-paragraph", "t": "VII - cópia da Anotação de Responsabilidade Técnica com identificação e assinatura do responsável técnico pelo projeto."}, {"c": "dou-paragraph", "t": "§ 1º Fica dispensada a apresentação dos documentos previstos nos incisos VI e VII para embarcação de pesca com comprimento total de até oito metros e potência de motor de até cinquenta HP."}, {"c": "dou-paragraph", "t": "§ 2º Quando se tratar de substituição de embarcação de pesca por desativação ou destruição, deverá ser apresentada declaração preenchida e assinada, conforme Anexo IV."}, {"c": "dou-paragraph", "t": "§ 3º Quando se tratar de substituição de embarcação de pesca por naufrágio, deverá ser apresentada cópia do comunicado de naufrágio expedido pela Autoridade Marítima."}, {"c": "dou-paragraph", "t": "§ 4º Quando a embarcação de pesca substituta já estiver construída, deverá ser apresentada, também, cópia do respectivo TIE ou do TIEM, com expedição até a data de publicação desta Portaria."}, {"c": "dou-paragraph", "t": "Seção IV"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento da renovação da Permissão Prévia de Pesca"}, {"c": "dou-paragraph", "t": "Art. 10. Para requerer a renovação da Permissão Prévia de Pesca, o responsável legal deverá apresentar formulário de requerimento devidamente preenchido e assinado, conforme Anexo III."}, {"c": "dou-paragraph", "t": "§ 1º A Permissão Prévia de Pesca poderá ser renovada uma única vez, por igual período, mediante justificativa apresentada pelo responsável legal."}, {"c": "dou-paragraph", "t": "§ 2º O requerimento de renovação deverá ser protocolado, preferencialmente, com antecedência mínima de trinta dias do término da vigência da Permissão Prévia de Pesca, admitido o protocolo até o último dia de sua validade."}, {"c": "dou-paragraph", "t": "§ 3º Expirada a vigência da Permissão Prévia de Pesca sem que tenha sido requerida sua renovação, ou encerrado o período de renovação previsto no § 1º sem a obtenção da respectiva Autorização de Pesca, o responsável legal deverá requerer nova Permissão Prévia de Pesca, mediante a instauração de novo procedimento administrativo."}, {"c": "dou-paragraph", "t": "Seção V"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento de obtenção de Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 11. Para requerer a Autorização de Pesca, o responsável legal deverá apresentar a seguinte documentação:"}, {"c": "dou-paragraph", "t": "I - formulário de requerimento devidamente preenchido e assinado, conforme Anexo I;"}, {"c": "dou-paragraph", "t": "II - cópia da Permissão Prévia de Pesca, quando exigida;"}, {"c": "dou-paragraph", "t": "III - cópia de comprovante de residência do responsável legal pessoa física, atualizado e emitido no máximo há três meses, ou autodeclaração de residência, conforme Anexo II, sendo que, no caso de responsável legal pessoa jurídica, o endereço será obtido pelo Ministério da Pesca e Aquicultura mediante consulta à base cadastral do Cadastro Nacional da Pessoa Jurídica  CNPJ;"}, {"c": "dou-paragraph", "t": "Art. 11 [...] IV - cópia do Memorial Descritivo que contenha as características básicas da embarcação de pesca, incluídos o comprimento total, a arqueação bruta, a arqueação líquida, a potência do motor, a capacidade do porão de armazenamento do pescado e a tancagem, com identificação e assinatura do responsável técnico pelo projeto;"}, {"c": "dou-paragraph", "t": "V - cópia da Anotação de Responsabilidade Técnica com identificação e assinatura do responsável técnico pelo projeto;"}, {"c": "dou-paragraph", "t": "VI - cópia do comprovante de recolhimento da taxa devida, quando aplicável, nos termos da legislação vigente;"}, {"c": "dou-paragraph", "t": "Art. 11 [...] VII - cópia válida e atualizada do TIE ou do TIEM, quando aplicável, no qual conste expressamente a atividade de pesca; e"}, {"c": "dou-paragraph", "t": "VIII - duas fotos coloridas da embarcação, uma mostrando-a pela popa (traseira) e outra pelo través (lado), de forma que apareça total e claramente de proa a popa."}, {"c": "dou-paragraph", "t": "§ 1º Fica dispensada a apresentação do documento previsto no inciso VII para as embarcações de pesca com comprimento total de até oito metros e potência de motor de até cinquenta HP."}, {"c": "dou-paragraph", "t": "§ 2º O responsável legal com idade entre dezoito e vinte e um anos poderá apresentar comprovante de residência em nome de membro do grupo familiar."}, {"c": "dou-paragraph", "t": "Seção VI"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento da renovação da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 12. Para requerer a renovação da Autorização de Pesca, o responsável legal deverá apresentar a seguinte documentação:"}, {"c": "dou-paragraph", "t": "I - formulário de requerimento devidamente preenchido e assinado, conforme Anexo I;"}, {"c": "dou-paragraph", "t": "Art. 12 [...] II - cópia do comprovante de recolhimento da taxa devida, quando aplicável, nos termos da legislação vigente;"}, {"c": "dou-paragraph", "t": "III - cópia do comprovante de residência do responsável legal pessoa física, atualizado e emitido no máximo há três meses, ou autodeclaração de residência, conforme Anexo II, sendo que, no caso de responsável legal pessoa jurídica, o endereço será obtido pelo Ministério da Pesca e Aquicultura mediante consulta à base cadastral do Cadastro Nacional da Pessoa Jurídica  CNPJ;"}, {"c": "dou-paragraph", "t": "IV - cópia válida e atualizada do Título de Inscrição de Embarcação - TIE ou do Título de Inscrição de Embarcação Miúda - TIEM, quando aplicável, no qual conste expressamente a atividade de pesca; e"}, {"c": "dou-paragraph", "t": "V - duas fotos coloridas da embarcação, uma mostrando-a pela popa (traseira) e outra pelo través (lado), de forma que apareça total e claramente de proa a popa."}, {"c": "dou-paragraph", "t": "Parágrafo único. O responsável legal com idade entre dezoito e vinte e um anos poderá apresentar comprovante de residência em nome de membro do grupo familiar."}, {"c": "dou-paragraph", "t": "Art. 13. A renovação da Autorização de Pesca deverá ser requerida, preferencialmente, com antecedência mínima de trinta dias do vencimento de sua vigência, admitida a apresentação do requerimento durante a vigência da Autorização de Pesca."}, {"c": "dou-paragraph", "t": "Seção VII"}, {"c": "dou-paragraph", "t": "Dos procedimentos para requerimento da atualização de dados da Permissão Prévia de Pesca e da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 14. Para requerer a atualização de dados constantes da Permissão Prévia de Pesca, da Autorização de Pesca ou de ambas, o responsável legal deverá apresentar a seguinte documentação:"}, {"c": "dou-paragraph", "t": "I - formulário de requerimento devidamente preenchido e assinado, conforme Anexo I;"}, {"c": "dou-paragraph", "t": "II - cópia válida e atualizada do TIE ou do TIEM, no qual conste expressamente a atividade de pesca;"}, {"c": "dou-paragraph", "t": "III - cópia de comprovante de residência do responsável legal pessoa física, atualizado e emitido no máximo há três meses, ou autodeclaração de residência, conforme Anexo II, sendo que, no caso de responsável legal pessoa jurídica, o endereço será obtido pelo Ministério da Pesca e Aquicultura mediante consulta à base cadastral do Cadastro Nacional da Pessoa Jurídica  CNPJ;"}, {"c": "dou-paragraph", "t": "IV - cópia do contrato de arrendamento da embarcação de pesca, devidamente preenchido e assinado pelas partes, conforme modelo constante do Anexo V, quando se tratar de arrendamento; e"}, {"c": "dou-paragraph", "t": "V - cópia de documentos complementares que comprovem a necessidade de atualização de dados."}, {"c": "dou-paragraph", "t": "§ 1º O responsável legal com idade entre dezoito e vinte e um anos poderá apresentar comprovante de residência em nome de membro do grupo familiar."}, {"c": "dou-paragraph", "t": "§ 2º Em caso de falecimento do responsável legal, enquanto não houver inventariante constituído, o cônjuge, o companheiro ou um dos herdeiros poderá requerer a atualização dos dados da embarcação de pesca, mediante apresentação da certidão de óbito e de documento que comprove o vínculo com o falecido, sem prejuízo dos demais documentos exigidos para a atualização de dados."}, {"c": "dou-paragraph", "t": "Art. 15. Após a concessão da Permissão Prévia de Pesca ou da Autorização de Pesca, o responsável legal deverá manter seus dados cadastrais atualizados no Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "Parágrafo único. Qualquer alteração cadastral no Registro Geral da Atividade Pesqueira deverá ser requerida no Sistema Eletrônico no prazo máximo de sessenta dias corridos, contado da data em que ocorrer a alteração."}, {"c": "dou-paragraph", "t": "Seção VIII"}, {"c": "dou-paragraph", "t": "Da análise do requerimento de Permissão Prévia de Pesca e da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 16. A análise dos requerimentos de Permissão Prévia de Pesca e de Autorização de Pesca de que trata esta Portaria será realizada mediante avaliação conjunta do formulário de requerimento e da documentação obrigatória apresentada, observados os requisitos estabelecidos nesta Portaria e nos atos normativos específicos de ordenamento pesqueiro aplicáveis."}, {"c": "dou-paragraph", "t": "§ 1º Compete à Superintendência Federal de Pesca e Aquicultura  SFPA da Unidade da Federação correspondente ao endereço do responsável legal realizar a análise dos requerimentos de que trata o caput, bem como decidir quanto ao seu deferimento ou indeferimento."}, {"c": "dou-paragraph", "t": "§ 2º As áreas técnicas de registro, monitoramento e ordenamento pesqueiro do Ministério da Pesca e Aquicultura poderão auxiliar subsidiariamente nas análises e procedimentos no Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "§ 3º No caso de deferimento, a Permissão Prévia de Pesca ou a Autorização de Pesca será concedida e disponibilizada ao responsável legal no Sistema Eletrônico do Registro Geral da Atividade Pesqueira, bem como encaminhada para o endereço eletrônico informado no requerimento."}, {"c": "dou-paragraph", "t": "§ 4º No caso de indeferimento, a unidade responsável pela análise deverá comunicar ao responsável legal o motivo da decisão, por meio do endereço eletrônico informado no requerimento ou constante do processo administrativo, assegurado o direito à interposição de recurso administrativo."}, {"c": "dou-paragraph", "t": "§ 5º A Permissão Prévia de Pesca ou a Autorização de Pesca será emitida, em formato digital, com assinatura eletrônica do Ministro de Estado da Pesca e Aquicultura, código de verificação e numeração única, e servirá como identificação cadastral da embarcação de pesca perante os órgãos e entidades competentes da administração pública."}, {"c": "dou-paragraph", "t": "§ 6º A Permissão Prévia de Pesca ou a Autorização de Pesca ficará disponível no Sistema Eletrônico do Registro Geral da Atividade Pesqueira e poderá ser impressa pelo responsável legal, em material de sua preferência, desde que preservados todos os seus elementos de autenticação, inclusive o código de verificação, e esteja legível e sem rasuras."}, {"c": "dou-paragraph", "t": "Art. 17. Compete à área técnica responsável pelo registro e monitoramento do Ministério da Pesca e Aquicultura analisar e decidir sobre os requerimentos de:"}, {"c": "dou-paragraph", "t": "I - substituição de embarcação de pesca; e"}, {"c": "dou-paragraph", "t": "II - conversão de modalidade de pesca."}, {"c": "dou-paragraph", "t": "§ 1º Os requerimentos de que trata o caput deverão ser previamente analisados pela área técnica competente pelo ordenamento do uso dos recursos pesqueiros, quanto aos aspectos relacionados à modalidade de pesca e às regras de ordenamento aplicáveis."}, {"c": "dou-paragraph", "t": "§ 2º Em caso de deferimento pela área técnica competente pelo ordenamento do uso dos recursos pesqueiros, o processo administrativo será encaminhado à área técnica responsável pelo registro e monitoramento para análise e decisão quanto aos aspectos de registro e monitoramento da atividade pesqueira."}, {"c": "dou-paragraph", "t": "§ 3º No caso de indeferimento pela área técnica competente pelo ordenamento do uso dos recursos pesqueiros, a área técnica deverá comunicar ao responsável legal, por meio do endereço eletrônico informado no requerimento ou constante do processo administrativo, com a indicação dos motivos da decisão, assegurado o direito à interposição de recurso administrativo, sem prejuízo da aplicação das sanções previstas nesta Portaria."}, {"c": "dou-paragraph", "t": "§ 4º Em caso de deferimento pela área técnica responsável pelo registro e monitoramento, esta deverá adotar as providências necessárias no Sistema Eletrônico do Registro Geral da Atividade Pesqueira para a concessão da Permissão Prévia de Pesca ou da Autorização de Pesca, que será disponibilizada ao responsável legal no sistema e encaminhada ao endereço eletrônico informado no requerimento."}, {"c": "dou-paragraph", "t": "§5º No caso de indeferimento pela área técnica responsável pelo registro e monitoramento, esta deverá comunicar ao responsável legal, por meio do endereço eletrônico informado no requerimento ou constante do processo administrativo, com a indicação dos motivos da decisão, assegurado o direito à interposição de recurso administrativo, sem prejuízo da aplicação das sanções previstas nesta Portaria."}, {"c": "dou-paragraph", "t": "Art. 18. Quando a Permissão Prévia de Pesca ou a Autorização de Pesca for entregue presencialmente na sede do Ministério da Pesca e Aquicultura ou na Superintendência Federal de Pesca e Aquicultura, o servidor responsável deverá providenciar cópia impressa do documento para entrega ao responsável legal."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "DAS SANÇÕES ADMINISTRATIVAS"}, {"c": "dou-paragraph", "t": "Art. 19. As sanções administrativas aplicáveis às embarcações de pesca, no âmbito desta Portaria, são:"}, {"c": "dou-paragraph", "t": "I - suspensão da Autorização de Pesca;"}, {"c": "dou-paragraph", "t": "II - cancelamento da Permissão Prévia de Pesca; e"}, {"c": "dou-paragraph", "t": "III - cancelamento da Autorização de Pesca."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Do procedimento de suspensão da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 20. A suspensão da Autorização de Pesca será aplicada, observado o procedimento previsto nesta Portaria, nas seguintes hipóteses:"}, {"c": "dou-paragraph", "t": "Art. 20 [...] I - quando não forem atendidas as obrigações previstas nas normas específicas de monitoramento e ordenamento da atividade pesqueira, nas hipóteses em que a legislação aplicável estabelecer a suspensão da Autorização de Pesca;"}, {"c": "dou-paragraph", "t": "II - em cumprimento de decisão judicial ou de órgão de controle que determine expressamente a suspensão; e"}, {"c": "dou-paragraph", "t": "III - quando houver comunicação do órgão ambiental fiscalizador ao Ministério da Pesca e Aquicultura acerca de decisão administrativa irrecorrível que determine ou implique a suspensão da atividade pesqueira da embarcação."}, {"c": "dou-paragraph", "t": "Art. 21. A aplicação da suspensão da Autorização de Pesca observará o procedimento previsto no art. 24."}, {"c": "dou-paragraph", "t": "§ 1º Após a manifestação do responsável legal ou o decurso do prazo para sua apresentação, a autoridade competente decidirá, de forma motivada, sobre a aplicação da suspensão."}, {"c": "dou-paragraph", "t": "§ 2º A decisão de suspensão será comunicada ao responsável legal, por meio do endereço eletrônico informado no requerimento apresentado no Sistema Eletrônico do Registro Geral da Atividade Pesqueira ou constante do processo administrativo, com a indicação dos motivos da decisão e das condições para sua reativação."}, {"c": "dou-paragraph", "t": "§ 3º Após a suspensão, o responsável legal poderá requerer a reativação da Autorização de Pesca, quando cabível, mediante solicitação no Sistema Eletrônico do Registro Geral da Atividade Pesqueira, desde que comprovado o saneamento dos motivos que ensejaram a sanção."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Do cancelamento da Permissão Prévia de Pesca e da Autorização de Pesca"}, {"c": "dou-paragraph", "t": "Art. 22. O cancelamento da Permissão Prévia de Pesca ou da Autorização de Pesca será aplicado nas seguintes hipóteses:"}, {"c": "dou-paragraph", "t": "I - quando não forem atendidas as obrigações previstas nas normas específicas de monitoramento e ordenamento da atividade pesqueira, nas hipóteses em que a legislação aplicável estabelecer o cancelamento da Permissão Prévia de Pesca ou da Autorização de Pesca;"}, {"c": "dou-paragraph", "t": "II - em cumprimento de decisão judicial ou de órgão de controle que determine o cancelamento;"}, {"c": "dou-paragraph", "t": "III - quando houver comunicação do órgão ambiental fiscalizador ao Ministério da Pesca e Aquicultura sobre condenação da embarcação de pesca por infração ambiental que tenha correlação com a atividade pesqueira, após decisão administrativa irrecorrível;"}, {"c": "dou-paragraph", "t": "IV - quando comprovada a operação da embarcação de pesca no exercício da atividade pesqueira exclusivamente com Permissão Prévia de Pesca; e"}, {"c": "dou-paragraph", "t": "V - quando a embarcação de pesca for objeto de venda, arrendamento, comodato, aquisição, transformação, substituição ou conversão, sem a anuência do Ministério da Pesca e Aquicultura, quando exigida."}, {"c": "dou-paragraph", "t": "Art. 23. O cancelamento da Permissão Prévia de Pesca ou da Autorização de Pesca será efetivado pela área técnica responsável pelo registro e monitoramento no Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "§ 1º O cancelamento da Autorização de Pesca implicará a paralisação imediata da operação da embarcação de pesca no exercício da atividade pesqueira."}, {"c": "dou-paragraph", "t": "§ 2º Nos casos de cancelamento da Autorização de Pesca, o responsável legal que pretenda voltar a exercer a atividade pesqueira deverá requerer nova Autorização de Pesca, observados os requisitos estabelecidos nesta Portaria e nas normas de ordenamento pesqueiro aplicáveis."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Da aplicação das sanções e do recurso administrativo"}, {"c": "dou-paragraph", "t": "Art. 24. A aplicação das sanções administrativas previstas neste Capítulo será precedida de notificação do responsável legal para que apresente manifestação no prazo de trinta dias corridos, ressalvadas as hipóteses de cumprimento de decisão judicial ou de órgão de controle que determine sua aplicação imediata."}, {"c": "dou-paragraph", "t": "§ 1º A notificação será realizada por meio do endereço eletrônico informado no requerimento ou constante do processo administrativo e deverá indicar os fatos e fundamentos que ensejam a aplicação da sanção."}, {"c": "dou-paragraph", "t": "§ 2º A ausência de manifestação no prazo estabelecido no caput não acarreta a aplicação automática da sanção administrativa, que dependerá de decisão motivada, após a verificação dos seus pressupostos."}, {"c": "dou-paragraph", "t": "Art. 25. Caberá recurso administrativo das decisões relativas à Permissão Prévia de Pesca e à Autorização de Pesca proferidas com fundamento nesta Portaria, por razões de legalidade e de mérito, inclusive nos casos de indeferimento, suspensão ou cancelamento."}, {"c": "dou-paragraph", "t": "§ 1º O recurso administrativo poderá ser interposto no prazo de dez dias, contado da ciência da decisão pelo responsável legal, conforme formulário constante do Anexo VI."}, {"c": "dou-paragraph", "t": "§ 2º O recurso será dirigido à autoridade que proferiu a decisão, que, se não a reconsiderar no prazo de cinco dias, o encaminhará à autoridade superior."}, {"c": "dou-paragraph", "t": "§ 3º O recurso deverá ser fundamentado e poderá ser acompanhado dos documentos que o recorrente considerar pertinentes, inclusive daqueles destinados a demonstrar, quando cabível, a inexistência ou o saneamento dos motivos que ensejaram a decisão recorrida."}, {"c": "dou-paragraph", "t": "§ 4º O recurso não será conhecido nas hipóteses previstas no art. 63 da Lei nº 9.784, de 29 de janeiro de 1999."}, {"c": "dou-paragraph", "t": "§ 5º Se não houver recurso no prazo previsto no § 1º, a decisão será considerada definitiva no âmbito administrativo."}, {"c": "dou-paragraph", "t": "Art. 26. O recurso administrativo deverá ser decidido no prazo de até trinta dias, prorrogável por igual período, mediante justificativa devidamente fundamentada."}, {"c": "dou-paragraph", "t": "Art. 27. O órgão competente para decidir o recurso poderá confirmar, modificar, anular ou revogar, total ou parcialmente, a decisão recorrida, observados os limites de sua competência."}, {"c": "dou-paragraph", "t": "Parágrafo único. Se a decisão do recurso puder resultar em situação mais desfavorável ao recorrente, este deverá ser previamente comunicado para apresentar suas alegações antes da decisão final."}, {"c": "dou-paragraph", "t": "Art. 28. Mantida a suspensão da Autorização de Pesca após o julgamento do recurso administrativo, a medida permanecerá vigente até o cumprimento do prazo ou da condição estabelecida na norma ou na decisão que fundamentou sua aplicação."}, {"c": "dou-paragraph", "t": "§ 1º Cumprido o prazo ou sanados os motivos que ensejaram a suspensão, conforme o caso, o responsável legal poderá solicitar a reativação da Autorização de Pesca mediante requerimento no Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "§ 2º O cancelamento da Autorização de Pesca, quando cabível, observará as hipóteses previstas no art. 22 e o procedimento estabelecido nesta Portaria."}, {"c": "dou-paragraph", "t": "Seção IV"}, {"c": "dou-paragraph", "t": "Do arquivamento"}, {"c": "dou-paragraph", "t": "Art. 29. O processo administrativo será arquivado nas seguintes hipóteses:"}, {"c": "dou-paragraph", "t": "I - exaurimento da instância administrativa;"}, {"c": "dou-paragraph", "t": "II - após o decurso do prazo para interposição de recurso administrativo sem a sua interposição pelo responsável legal; ou"}, {"c": "dou-paragraph", "t": "III - quando o responsável legal deixar de atender diligência indispensável à análise do pedido, nos termos do art. 40 da Lei nº 9.784, de 29 de janeiro de 1999."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "DAS DISPOSIÇÕES TRANSITÓRIAS E FINAIS"}, {"c": "dou-paragraph", "t": "Art. 30. O prazo para análise e instrução dos requerimentos no Sistema Eletrônico do Registro Geral da Atividade Pesqueira será de até sessenta dias, contado do recebimento da documentação necessária, prorrogável por igual período, mediante justificativa."}, {"c": "dou-paragraph", "t": "Parágrafo único. Concluída a instrução do requerimento, será observado o prazo para decisão previsto no art. 49 da Lei nº 9.784, de 29 de janeiro de 1999."}, {"c": "dou-paragraph", "t": "Art. 31. O responsável legal poderá requerer, a qualquer tempo, o cancelamento da Permissão Prévia de Pesca ou da Autorização de Pesca no Sistema Eletrônico do Registro Geral da Atividade Pesqueira."}, {"c": "dou-paragraph", "t": "Art. 32. O responsável legal da embarcação de pesca deverá indicar, de forma visível, no casco da embarcação, o respectivo número de inscrição no Registro Geral da Atividade Pesqueira, observados os critérios e padrões estabelecidos pela legislação da Autoridade Marítima ou em ato normativo específico complementar."}, {"c": "dou-paragraph", "t": "Parágrafo único. O responsável legal terá o prazo de um ano, contado da entrada em vigor desta Portaria, para adequação ao disposto no caput."}, {"c": "dou-paragraph", "t": "Art. 33. As Superintendências Federais de Pesca e Aquicultura nas unidades da Federação deverão prestar atendimento presencial ao responsável legal, com a finalidade de auxiliar o acesso ao Sistema Eletrônico do Registro Geral da Atividade Pesqueira e a inserção da documentação necessária ao processamento dos requerimentos previstos nesta Portaria."}, {"c": "dou-paragraph", "t": "Art. 34. O responsável legal responderá pela veracidade das informações e dos dados prestados no âmbito dos procedimentos previstos nesta Portaria e ficará sujeito às sanções administrativas, civis e penais cabíveis em caso de prestação de informações ou dados falsos."}, {"c": "dou-paragraph", "t": "Art. 35. O responsável legal poderá constituir procurador para representá-lo perante o Ministério da Pesca e Aquicultura nos atos e procedimentos administrativos previstos nesta Portaria, mediante apresentação de instrumento de procuração válido."}, {"c": "dou-paragraph", "t": "Parágrafo único. A representação por procurador confere ao procurador a condição de responsável legal da embarcação de pesca."}, {"c": "dou-paragraph", "t": "Art. 36. Os procedimentos administrativos estabelecidos nesta Portaria não dispensam o cumprimento dos procedimentos específicos previstos nas normas de registro, monitoramento e ordenamento dos recursos pesqueiros, quando aplicáveis."}, {"c": "dou-paragraph", "t": "Art. 37. Os casos omissos serão decididos pelo Ministério da Pesca e Aquicultura."}, {"c": "dou-paragraph", "t": "Art. 38. Esta Portaria entra em vigor noventa dias após a data de sua publicação."}, {"c": "assina", "t": "RIVETLA EDIPO ARAUJO CRUZ"}, {"c": "anexo", "t": "ANEXO I"}, {"c": "dou-paragraph", "t": "FORMULÁRIO DE REQUERIMENTO DA CATEGORIA DE EMBARCAÇÃO DE PESCA EM ÁGUAS CONTINENTAIS"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPREQUERIMENTO DA CATEGORIA DE EMBARCAÇÃO DE PESCA EM ÁGUAS CONTINENTAIS"}, {"c": "", "t": "A"}, {"c": "", "t": "CARACTERIZAÇÃO DO REQUERIMENTO"}, {"c": "", "t": "1. SOLICITAÇÃO*:"}, {"c": "", "t": "( ) PERMISSÃO PRÉVIA DE PESCA - PPP( ) AUTORIZAÇÃO DE PESCA - RAEPDESCREVA DE FORMA RESUMIDA A SOLICITAÇÃO: __________________________"}, {"c": "", "t": "2. MOTIVO DO PREENCHIMENTO*:"}, {"c": "", "t": "( ) CONSTRUÇÃO DE EMBARCAÇÃO( ) REGISTRO INICIAL( ) RENOVAÇÃO( ) ATUALIZAÇÃO DE DADOS( ) TRANSFORMAÇÃO DE CARACTERÍSTICAS DE EMBARCAÇÃO"}, {"c": "", "t": "( ) CONVERSÃO DE MODALIDADE DE PERMISSIONAMENTO( ) SUBSTITUIÇÃO DE EMBARCAÇÃO( ) CANCELAMENTO( ) OUTROS:____________________________________________________________________________________"}, {"c": "", "t": "3. MODALIDADE DE PERMISSIONAMENTO (anexo danormade permissionamento)*:"}, {"c": "", "t": "( ) Amazônica ( ) Tocantins-Araguaia ( )Atlântico Nordeste Ocidental ( ) Atlântico Nordeste Oriental ( ) Parnaíba ( ) Atlântico Leste ( ) São Francisco"}, {"c": "", "t": "*PREENCHIMENTO OBRIGATÓRIO"}, {"c": "", "t": "B"}, {"c": "", "t": "IDENTIFICAÇÃO E CARACTERÍSTICAS DA EMBARCAÇÃO DE PESCA"}, {"c": "", "t": "1. NOME DA EMBARCAÇÃO*:"}, {"c": "", "t": "2.UF*:"}, {"c": "", "t": "3. Nº DO TIE/TIEM/PRPM*"}, {"c": "", "t": "4. Nº DO RGP (quando houver)*"}, {"c": "", "t": "5. Nº DO CADASTRO TÉCNICO FEDERAL - CTF*"}, {"c": "", "t": "6. EMBARCAÇÃO ARRENDADA?"}, {"c": "", "t": "( ) SIM ( ) NÃO"}, {"c": "", "t": "7. ORIGEM DA EMBARCAÇÃO*:"}, {"c": "", "t": "( ) CONSTRUÍDA NO BRASIL ( ) BRASILEIRA ( ) NACIONALIZADA ( ) ESTRANGEIRA - PAÍS:___________________"}, {"c": "", "t": "8. ANO DE CONSTRUÇÃO*"}, {"c": "", "t": "9.TIPO DE PROPULSÃO*:"}, {"c": "", "t": "10.POTÊNCIA (HP)*:"}, {"c": "", "t": "11. ARQUEAÇÃO BRUTA*:"}, {"c": "", "t": "12. COMPRIMENTO*:"}, {"c": "", "t": "( )MOTOR ( )REMO ( )VELA"}, {"c": "", "t": "( ) DIESEL ( ) GASOLINA"}, {"c": "", "t": "13. CAPACIDADE DO PORÃO (M³ OU TONELADA)*:"}, {"c": "", "t": "14. TANCAGEM DE COMBUSTÍVEL (L)*:"}, {"c": "", "t": "15. TIPO DE COMBUSTÍVEL*:"}, {"c": "", "t": "( ) DIESEL ( ) GASOLINA ( ) OUTROS"}, {"c": "", "t": "16. MATERIAL DO CASCO*:"}, {"c": "", "t": "( ) AÇO ( ) ALUMÍNIO ( ) FERRO CIMENTO ( ) FIBRA DE VIDRO ( ) MADEIRA ( ) FERRO"}, {"c": "", "t": "*PREENCHIMENTO OBRIGATÓRIO"}, {"c": "", "t": "C"}, {"c": "", "t": "IDENTIFICAÇÃO DO RESPONSÁVEL LEGAL DA EMBARCAÇÃO DE PESCA*:"}, {"c": "", "t": "1. NOME DO PROPRIETÁRIO*:"}, {"c": "", "t": "2. Nº DO RG*:"}, {"c": "", "t": "3. ÓRGÃO EMISSOR / UF*:"}, {"c": "", "t": "4. DATA DE EMISSÃO*:"}, {"c": "", "t": "5. CPF/CNPJ*:"}, {"c": "", "t": "6. ENDEREÇO DO INTERESSADO (RUA, AVENIDA, NÚMERO, COMPLEMENTO)*:"}, {"c": "", "t": "7. BAIRRO*:"}, {"c": "", "t": "8. MUNICÍPIO*:"}, {"c": "", "t": "9. UF*:"}, {"c": "", "t": "10. CEP*:"}, {"c": "", "t": "11. DDD + TELEFONE*:"}, {"c": "", "t": "12. DDD + WHATSAPP:"}, {"c": "", "t": "13. E-MAIL*:"}, {"c": "", "t": "( )Autodeclaração de residência:Declaro para os devidos fins, sob as penas da Lei, ser residente e domiciliado no endereço descrito acima, e estou ciente de que a falsidade da presente declaração pode implicar na sanção penal prevista no Art. 299 do Código Penal."}, {"c": "", "t": "*PREENCHIMENTO OBRIGATÓRIO"}, {"c": "", "t": "D"}, {"c": "", "t": "IDENTIFICAÇÃO DA ENTIDADE REPRESENTATIVA OU DESPACHANTE, QUANDO SE APLICAR*:"}, {"c": "", "t": "1. FILIADO A ENTIDADE REPRESENTATIVA*:"}, {"c": "", "t": "2. TIPO DE ENTIDADE*:"}, {"c": "", "t": "( ) SIM ( ) NÃO"}, {"c": "", "t": "( ) COLÔNIA ( ) ASSOCIAÇÃO ( ) SINDICATO ( ) OUTRO"}, {"c": "", "t": "3. NOME DA ENTIDADE À QUAL É FILIADO*:"}, {"c": "", "t": "4. Nº DO CPF/CNPJ:"}, {"c": "", "t": "5. ENDEREÇO (RUA, AVENIDA, NÚMERO E CEP)*:"}, {"c": "", "t": "6. MUNICÍPIO*:"}, {"c": "", "t": "7. BAIRRO*:"}, {"c": "", "t": "8. UF:"}, {"c": "", "t": "9. DDD + TELEFONE 1*:"}, {"c": "", "t": "10. DDD + TELEFONE 2:"}, {"c": "", "t": "11. DDD + WHATSAPP:"}, {"c": "", "t": "12. E-MAIL*:"}, {"c": "", "t": "*PREENCHIMENTO OBRIGATÓRIO"}, {"c": "", "t": "TERMO DE RESPONSABILIDADE DO REQUERENTE:"}, {"c": "", "t": "Assumo total responsabilidade pelas informações aqui prestadas, bem como assumo o compromisso de cumprir com a legislação vigente. Estou ciente que a declaração falsa constitui crime previsto no art. 299 do Código Penal._________________, ____ de _________________ de ______. _____________________________________"}, {"c": "", "t": "Local Data Assinatura**ASSINATURA LEGÍVEL OBRIGATÓRIA OU ASSINATURA DIGITAL."}, {"c": "dou-paragraph", "t": "Toda solicitação do interessado que estiver em desconformidade com o referido requerimento, será devidamente INDEFERIDA."}, {"c": "dou-paragraph", "t": "ANEXO II"}, {"c": "dou-paragraph", "t": "AUTODECLARAÇÃO DE RESIDÊNCIA DO RESPONSÁVEL LEGAL"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPAUTODECLARAÇÃO DE RESIDÊNCIA DO RESPONSÁVEL LEGAL"}, {"c": "dou-paragraph", "t": "Eu, __________________________________________________, documento de identidade nº: ______________________, órgão exp. _______________, CPF:______________________, nacionalidade:_______________________, naturalidade: ____________________, telefone (DDD e nº): _____________________, celular (DDD e nº):_____________________________."}, {"c": "dou-paragraph", "t": "DECLARO para os devidos fins, com base na Lei nº 7.115, de 29 de agosto de 1983, ser residente e domiciliado(a) no endereço:"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "Declaro ainda, estar ciente que a falsidade da presente declaração pode implicar na sanção penal prevista no Art. 299 do Código Penal, conforme transcrição abaixo:"}, {"c": "dou-paragraph", "t": "\"Art. 299 - Omitir, em documento público ou particular, declaração que nele deveria constar, ou nele inserir ou fazer inserir Declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre o fato juridicamente relevante. Pena: reclusão de 1 (um) a 5 (cinco) anos e multa, se o documento é público e reclusão de 1 (um) a 3 (três) anos, se o documento é particular.\""}, {"c": "dou-paragraph", "t": "_____________________,___________/ _________ / ________"}, {"c": "dou-paragraph", "t": "Local Data"}, {"c": "dou-paragraph", "t": "___________________________________"}, {"c": "dou-paragraph", "t": "Assinatura do Responsável Legal"}, {"c": "anexo", "t": "ANEXO III"}, {"c": "dou-paragraph", "t": "FORMULÁRIO DE RENOVAÇÃO DA PERMISSÃO PRÉVIA DE PESCA"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPFORMULÁRIO DE REQUERIMENTO PARA RENOVAÇÃO DA PERMISSÃO PRÉVIA DE PESCA"}, {"c": "dou-paragraph", "t": "1. IDENTIFICAÇÃO DO RESPONSÁVEL LEGAL"}, {"c": "dou-paragraph", "t": "Nome/Razão Social: ______________________________________________________"}, {"c": "dou-paragraph", "t": "CPF/CNPJ: ______________________________________________________________"}, {"c": "dou-paragraph", "t": "E-mail: _________________________________________________________________"}, {"c": "dou-paragraph", "t": "Telefone: ______________________________________________________________"}, {"c": "dou-paragraph", "t": "2. IDENTIFICAÇÃO DA EMBARCAÇÃO DE PESCA"}, {"c": "dou-paragraph", "t": "Nome da embarcação: ____________________________________________________"}, {"c": "dou-paragraph", "t": "Número de inscrição no RGP: _____________________________________________"}, {"c": "dou-paragraph", "t": "Número da Permissão Prévia de Pesca: ____________________________________"}, {"c": "dou-paragraph", "t": "Data de vencimento da Permissão Prévia de Pesca:____________/____________/____________"}, {"c": "dou-paragraph", "t": "3. JUSTIFICATIVA PARA RENOVAÇÃO"}, {"c": "dou-paragraph", "t": "Declaro, para os devidos fins, que solicito a renovação da Permissão Prévia de Pesca pelo período previsto na regulamentação, em razão de:"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "4. DECLARAÇÃO"}, {"c": "dou-paragraph", "t": "Declaro, sob as penas da lei, que as informações prestadas neste requerimento são verdadeiras e que estou ciente de que a Permissão Prévia de Pesca não autoriza a operação da embarcação de pesca, ficando sua utilização condicionada à obtenção da respectiva Autorização de Pesca, quando exigida."}, {"c": "dou-paragraph", "t": "Local e data: ______________________________, ____________/____________/____________"}, {"c": "dou-paragraph", "t": "Nome do responsável legal: ______________________________________________"}, {"c": "dou-paragraph", "t": "Assinatura do responsável legal: _________________________________________"}, {"c": "anexo", "t": "ANEXO IV"}, {"c": "dou-paragraph", "t": "DECLARAÇÃO DE DESATIVAÇÃO DA EMBARCAÇÃO DE PESCA"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPDECLARAÇÃO DE DESATIVAÇÃO DA EMBARCAÇÃO DE PESCA"}, {"c": "dou-paragraph", "t": "Eu, __________________________________________________, documento de identidade nº: ______________________, órgão exp. _______________, CPF:______________________, nacionalidade:_______________________, naturalidade: ____________________, telefone (DDD e nº): _____________________, celular (DDD e nº):_____________________________."}, {"c": "dou-paragraph", "t": "DECLARO para os devidos fins, sob penas da Lei, que a embarcação de pesca ___________________, inscrita na Autoridade Marítima pelo nº ________________ e no Registro Geral da Atividade Pesqueira - RGP pelo nº ______________, encontra-se definitivamente desativada para o exercício da atividade pesqueira, por isso, renuncio, em caráter definitivo e irrevogável, a Autorização de Pesca concedida."}, {"c": "dou-paragraph", "t": "Declaro, ainda, estar ciente que a falsidade da presente declaração pode implicar na sanção penal prevista no Art. 299 do Código Penal, conforme transcrição abaixo:"}, {"c": "dou-paragraph", "t": "\"Art. 299 - Omitir, em documento público ou particular, declaração que nele deveria constar, ou nele inserir ou fazer inserir Declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre o fato juridicamente relevante. Pena: reclusão de 1 (um) a 5 (cinco) anos e multa, se o documento é público e reclusão de 1 (um) a 3 (três) anos, se o documento é particular.\""}, {"c": "dou-paragraph", "t": "_____________________,___________/ _________ / ________"}, {"c": "dou-paragraph", "t": "Local Data"}, {"c": "dou-paragraph", "t": "___________________________________"}, {"c": "dou-paragraph", "t": "Assinatura do Responsável Legal"}, {"c": "anexo", "t": "ANEXO V"}, {"c": "dou-paragraph", "t": "CONTRATO DE ARRENDAMENTO DE EMBARCAÇÃO DE PESCA"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPCONTRATO DE ARRENDAMENTO DE EMBARCAÇÃO DE PESCA"}, {"c": "dou-paragraph", "t": "Pelo presente instrumento particular, de um lado:"}, {"c": "dou-paragraph", "t": "ARRENDANTE: [nome completo ou razão social], [nacionalidade], [estado civil, quando pessoa física], inscrito(a) no CPF/CNPJ sob o nº _____________________, com endereço em ___________________________, neste ato representado, quando pessoa jurídica, por [nome do representante legal], inscrito no CPF sob o nº _____________________, doravante denominado ARRENDANTE;"}, {"c": "dou-paragraph", "t": "e, de outro lado:"}, {"c": "dou-paragraph", "t": "ARRENDATÁRIO: [nome completo ou razão social], [nacionalidade], [estado civil, quando pessoa física], inscrito(a) no CPF/CNPJ sob o nº _____________________, com endereço em ___________________________, neste ato representado, quando pessoa jurídica, por [nome do representante legal], inscrito no CPF sob o nº _____________________, doravante denominado ARRENDATÁRIO;"}, {"c": "dou-paragraph", "t": "Têm entre si justo e contratado o presente Contrato de Arrendamento de Embarcação de Pesca, mediante as cláusulas e condições seguintes:"}, {"c": "dou-paragraph", "t": "CLÁUSULA PRIMEIRA - DO OBJETO"}, {"c": "dou-paragraph", "t": "1.1. O presente contrato tem por objeto o arrendamento da embarcação de pesca abaixo identificada:"}, {"c": "dou-paragraph", "t": "I - nome da embarcação: ___________________________"}, {"c": "dou-paragraph", "t": "II - número de inscrição da embarcação no RGP: _______________________"}, {"c": "dou-paragraph", "t": "III - número do Título de Inscrição de Embarcação - TIE ou do Título de Inscrição de Embarcação Miúda - TIEM:"}, {"c": "dou-paragraph", "t": "______________________________________"}, {"c": "dou-paragraph", "t": "1.2. O ARRENDANTE declara ser proprietário ou possuir legitimidade para arrendar a embarcação de pesca objeto deste contrato, responsabilizando-se pela veracidade das informações prestadas."}, {"c": "dou-paragraph", "t": "CLÁUSULA SEGUNDA - DA FINALIDADE DO ARRENDAMENTO"}, {"c": "dou-paragraph", "t": "2.1. A embarcação de pesca objeto deste contrato será utilizada pelo ARRENDATÁRIO exclusivamente para o exercício da atividade pesqueira, observadas as normas de registro, monitoramento, ordenamento e demais disposições legais aplicáveis."}, {"c": "dou-paragraph", "t": "2.2. O presente contrato não autoriza, por si só, o exercício da atividade pesqueira quando a embarcação não estiver regularmente inscrita e autorizada para a atividade, na forma da legislação aplicável."}, {"c": "dou-paragraph", "t": "CLÁUSULA TERCEIRA - DO PRAZO"}, {"c": "dou-paragraph", "t": "3.1. O presente contrato terá vigência de ______ meses/anos, com início em ___/____/_____ e término em ___/____/_____."}, {"c": "dou-paragraph", "t": "3.2. Eventual prorrogação do prazo de arrendamento deverá ser formalizada por instrumento escrito e apresentada ao Ministério da Pesca e Aquicultura."}, {"c": "dou-paragraph", "t": "CLÁUSULA QUARTA - DO VALOR E DA FORMA DE PAGAMENTO"}, {"c": "dou-paragraph", "t": "4.1. Pelo arrendamento da embarcação, o ARRENDATÁRIO pagará ao ARRENDANTE o valor de R$____,__ , mediante [inserir forma de pagamento]."}, {"c": "dou-paragraph", "t": "4.2. As partes poderão estabelecer livremente as condições de pagamento, observada a legislação aplicável."}, {"c": "dou-paragraph", "t": "CLÁUSULA QUINTA - DAS OBRIGAÇÕES DO ARRENDANTE"}, {"c": "dou-paragraph", "t": "5.1. Constituem obrigações do ARRENDANTE:"}, {"c": "dou-paragraph", "t": "I - disponibilizar a embarcação ao ARRENDATÁRIO nas condições previstas neste contrato;"}, {"c": "dou-paragraph", "t": "II - fornecer ao ARRENDATÁRIO os documentos necessários à identificação e regularização da embarcação, quando de sua responsabilidade;"}, {"c": "dou-paragraph", "t": "III - comunicar ao ARRENDATÁRIO qualquer fato que possa comprometer a regularidade da embarcação ou a execução deste contrato; e"}, {"c": "dou-paragraph", "t": "IV - comunicar ao Ministério da Pesca e Aquicultura a extinção ou alteração do presente contrato."}, {"c": "dou-paragraph", "t": "CLÁUSULA SEXTA - DAS OBRIGAÇÕES DO ARRENDATÁRIO"}, {"c": "dou-paragraph", "t": "6.1. Constituem obrigações do ARRENDATÁRIO:"}, {"c": "dou-paragraph", "t": "I - utilizar a embarcação exclusivamente para a finalidade prevista neste contrato e de acordo com a legislação aplicável;"}, {"c": "dou-paragraph", "t": "II - manter a embarcação em condições regulares de operação durante o período do arrendamento, observadas as responsabilidades atribuídas pela legislação ao responsável legal;"}, {"c": "dou-paragraph", "t": "III - cumprir as normas de registro, monitoramento, ordenamento pesqueiro e segurança da navegação aplicáveis à atividade;"}, {"c": "dou-paragraph", "t": "IV - manter atualizados os dados e documentos relacionados ao arrendamento perante o Ministério da Pesca e Aquicultura;"}, {"c": "dou-paragraph", "t": "V - comunicar ao ARRENDANTE qualquer ocorrência que possa comprometer a regularidade da embarcação; e"}, {"c": "dou-paragraph", "t": "VI - devolver a embarcação ao ARRENDANTE ao término do contrato, nas condições previstas neste instrumento, ressalvado o desgaste decorrente do uso regular."}, {"c": "dou-paragraph", "t": "CLÁUSULA SÉTIMA - DA RESPONSABILIDADE PERANTE O PODER PÚBLICO"}, {"c": "dou-paragraph", "t": "7.1. O ARRENDATÁRIO responderá pelos atos praticados no exercício da atividade pesqueira durante o período de vigência do arrendamento, sem prejuízo das responsabilidades atribuídas ao ARRENDANTE pela legislação aplicável."}, {"c": "dou-paragraph", "t": "7.2. O arrendamento não afasta a necessidade de cumprimento das exigências estabelecidas pelo Ministério da Pesca e Aquicultura, pela Autoridade Marítima e pelos demais órgãos competentes."}, {"c": "dou-paragraph", "t": "CLÁUSULA OITAVA - DA RESCISÃO"}, {"c": "dou-paragraph", "t": "8.1. O presente contrato poderá ser rescindido:"}, {"c": "dou-paragraph", "t": "I - pelo término do prazo de vigência;"}, {"c": "dou-paragraph", "t": "II - por acordo entre as partes;"}, {"c": "dou-paragraph", "t": "III - pelo descumprimento de qualquer obrigação prevista neste contrato; ou"}, {"c": "dou-paragraph", "t": "IV - nas demais hipóteses previstas na legislação aplicável."}, {"c": "dou-paragraph", "t": "8.2. A extinção do contrato de arrendamento deverá ser comunicada ao Ministério da Pesca e Aquicultura."}, {"c": "dou-paragraph", "t": "CLÁUSULA NONA - DAS DISPOSIÇÕES GERAIS"}, {"c": "dou-paragraph", "t": "9.1. O presente contrato deverá corresponder às informações constantes dos documentos oficiais da embarcação de pesca e dos cadastros dos contratantes."}, {"c": "dou-paragraph", "t": "9.2. Qualquer alteração das informações constantes deste contrato deverá ser formalizada por escrito e, quando exigido, apresentada ao Ministério da Pesca e Aquicultura para atualização dos dados cadastrais da embarcação de pesca."}, {"c": "dou-paragraph", "t": "9.3. A apresentação deste contrato ao Ministério da Pesca e Aquicultura não substitui os demais documentos e requisitos exigidos para o registro, monitoramento e ordenamento da atividade pesqueira."}, {"c": "dou-paragraph", "t": "CLÁUSULA DÉCIMA - DO FORO"}, {"c": "dou-paragraph", "t": "10.1. Fica eleito o foro da comarca de [município/UF], para dirimir eventuais controvérsias decorrentes deste contrato, ressalvadas as hipóteses de competência legal diversa."}, {"c": "dou-paragraph", "t": "E, por estarem de acordo, as partes assinam o presente instrumento em [número] vias de igual teor e forma."}, {"c": "dou-paragraph", "t": "[Município/UF], [dia] de [mês] de [ano]."}, {"c": "dou-paragraph", "t": "ARRENDANTE"}, {"c": "dou-paragraph", "t": "Nome/Razão Social: ______________________________________"}, {"c": "dou-paragraph", "t": "CPF/CNPJ: ______________________________________________"}, {"c": "dou-paragraph", "t": "Assinatura: ______________________________________________"}, {"c": "dou-paragraph", "t": "ARRENDATÁRIO"}, {"c": "dou-paragraph", "t": "Nome/Razão Social: ______________________________________"}, {"c": "dou-paragraph", "t": "CPF/CNPJ: ______________________________________________"}, {"c": "dou-paragraph", "t": "Assinatura: ______________________________________________"}, {"c": "dou-paragraph", "t": "TESTEMUNHA 1"}, {"c": "dou-paragraph", "t": "Nome: _________________________________________________"}, {"c": "dou-paragraph", "t": "CPF: __________________________________________________"}, {"c": "dou-paragraph", "t": "Assinatura: ______________________________________________"}, {"c": "dou-paragraph", "t": "TESTEMUNHA 2"}, {"c": "dou-paragraph", "t": "Nome: _________________________________________________"}, {"c": "dou-paragraph", "t": "CPF: __________________________________________________"}, {"c": "dou-paragraph", "t": "Assinatura: ______________________________________________"}, {"c": "anexo", "t": "ANEXO VI"}, {"c": "dou-paragraph", "t": "FORMULÁRIO DE INTERPOSIÇÃO DE RECURSO ADMINISTRATIVO"}, {"c": "", "t": "MINISTÉRIO DA PESCA E AQUICULTURAREGISTRO GERAL DA ATIVIDADE PESQUEIRA - RGPINTERPOSIÇÃO DE RECURSO ADMINISTRATIVO"}, {"c": "dou-paragraph", "t": "Eu, __________________________________________________, documento de identidade nº: ______________________, órgão exp. _______________, CPF:______________________, nacionalidade:_______________________, naturalidade: ____________________, telefone (DDD e nº): _____________________, celular (DDD e nº):_____________________________."}, {"c": "dou-paragraph", "t": "APRESENTO para os devidos fins, o recurso administrativo contra a decisão proferida referente a embarcação de pesca ___________________, inscrita na Autoridade Marítima pelo nº ________________ e no Registro Geral da Atividade Pesqueira - RGP pelo nº ______________, conforme justificativas elencadas abaixo:"}, {"c": "dou-paragraph", "t": "_________________________________________________________________"}, {"c": "dou-paragraph", "t": "Como fundamentado, encaminho anexos os seguintes documentos comprobatórios:"}, {"c": "dou-paragraph", "t": "1)_____________________________________________________________________________________________________________________________________________"}, {"c": "dou-paragraph", "t": "2)_____________________________________________________________________________________________________________________________________________"}, {"c": "dou-paragraph", "t": "3)_____________________________________________________________________________________________________________________________________________"}, {"c": "dou-paragraph", "t": "_____________________,___________/ _________ / ________"}, {"c": "dou-paragraph", "t": "Local Data"}, {"c": "dou-paragraph", "t": "___________________________________"}, {"c": "dou-paragraph", "t": "Assinatura do Responsável Legal"}]});